    static boolean isPassing(Student student) {
        return student.average() >= PASSING_THRESHOLD;
    }

    public static void main(String[] args) {
        int year = 2026;                 // primitive variable: holds the value itself
        String section = "CS1-Java-A";   // reference variable: points to a String object

        Student alex = new Student("Alex", 88, 91, 84, 90);
        Student sam = new Student("Sam", 72, 67, 75, 70);
        Student kai = new Student("Kai", 55, 62, 70, 58);

        System.out.println("Section: " + section + " (" + year + ")");
        for (Student student : new Student[]{alex, sam, kai}) {
            System.out.println(student.summary());
            System.out.println("Status: " + (isPassing(student) ? "PASS" : "REVIEW"));
        }
    }
}

class Student {
    private final String name;
    private final int[] scores;

    // int... lets callers pass any number of scores; Java packs them into an int[]
    Student(String name, int... scores) {
        this.name = name;
        this.scores = scores;
    }

    double average() {
        int total = 0;
        for (int score : scores) {
            total += score;
        }
        // Cast before dividing, otherwise int / int truncates
        return scores.length == 0 ? 0.0 : total / (double) scores.length;
    }

    char letterGrade() {
        double avg = average();
        if (avg >= 90) return 'A';
        if (avg >= 80) return 'B';
        if (avg >= 70) return 'C';
        if (avg >= 60) return 'D';
        return 'F';
    }

    String summary() {
        return name + " scores=" + Arrays.toString(scores)
            + ", avg=" + String.format("%.2f", average())
            + ", letter=" + letterGrade();
    }
}

