import java.util.Arrays;

public class VariablesCopySemantics {
    public static void main(String[] args) {
        // Primitive: the variable holds the value, so assignment copies the number
        int a = 5;
        int b = a;
        b = b + 10;
        System.out.println("a = " + a + ", b = " + b + " (b got a copy of the value)");

        // Reference: the variable holds an arrow to the array, so assignment copies the arrow
        int[] x = {1, 2, 3};
        int[] y = x;
        y[0] = 99;
        System.out.println("x = " + Arrays.toString(x) + ", y = " + Arrays.toString(y)
            + " (y copied the reference)");

        final int MAX_CREDITS = 18;   // final: assigned once, MAX_CREDITS = 20 would not compile
        int credits = 12;
        int before = credits;
        credits += 3;                 // compound assignment
        System.out.println("credits: " + before + " -> " + credits + " (max " + MAX_CREDITS + ")");

        {
            int bonus = 2;            // block scope: bonus exists only inside these braces
            credits += bonus;
            System.out.println("inside block: bonus = " + bonus + ", credits = " + credits);
        }
        // System.out.println(bonus);  // would not compile: bonus is out of scope
        System.out.println("after block: credits = " + credits + " (bonus is out of scope)");
    }
}

