public class DataTypesArithmetic {
    public static void main(String[] args) {
        // The operand types pick the operation: int / int is integer division
        System.out.println("7 / 2 = " + (7 / 2));
        System.out.println("7 / 2.0 = " + (7 / 2.0));
        // Integer division truncates toward zero; % keeps the sign of the left operand
        System.out.println("-7 / 2 = " + (-7 / 2));
        System.out.println("-7 % 2 = " + (-7 % 2));
        // A cast to int drops the fraction, it does not round
        System.out.println("(int) 3.99 = " + (int) 3.99);

        int max = Integer.MAX_VALUE;
        System.out.println("Integer.MAX_VALUE = " + max);
        System.out.println("MAX_VALUE + 1 = " + (max + 1));     // 32-bit overflow wraps silently
        System.out.println("MAX_VALUE + 1L = " + (max + 1L));   // 1L makes the sum a 64-bit long

        char letter = 'A';
        int code = letter + 2;                 // char is promoted to int in arithmetic
        System.out.println("'A' + 2 = " + code + " -> " + (char) code);

        double sum = 0.1 + 0.2;                // binary doubles cannot store 0.1 exactly
        System.out.println("0.1 + 0.2 = " + sum);
        System.out.println("0.1 + 0.2 == 0.3? " + (sum == 0.3));
    }
}

