#include <cstdint>
#include <iomanip>
#include <iostream>
#include <limits>

int main() {
    std::cout << "7 / 2 = " << 7 / 2 << "\n";
    std::cout << "7 / 2.0 = " << 7 / 2.0 << "\n";
    // Like Java, C++ integer division truncates toward zero
    std::cout << "-7 / 2 = " << -7 / 2 << "\n";
    std::cout << "-7 % 2 = " << -7 % 2 << "\n";
    std::cout << "(int) 3.99 = " << static_cast<int>(3.99) << "\n";

    std::int32_t max = std::numeric_limits<std::int32_t>::max();
    std::cout << "Integer.MAX_VALUE = " << max << "\n";
    // Signed overflow is undefined behavior in C++, so wrap explicitly through unsigned math
    std::int32_t wrapped = static_cast<std::int32_t>(static_cast<std::uint32_t>(max) + 1u);
    std::cout << "MAX_VALUE + 1 = " << wrapped << "\n";
    std::cout << "MAX_VALUE + 1L = " << static_cast<std::int64_t>(max) + 1 << "\n";

    char letter = 'A';
    int code = letter + 2;  // char promotes to int, as in Java (but C++ char is 8 bits)
    std::cout << "'A' + 2 = " << code << " -> " << static_cast<char>(code) << "\n";

    double sum = 0.1 + 0.2;
    // 17 significant digits reveal the rounding error that Java prints by default
    std::cout << "0.1 + 0.2 = " << std::setprecision(17) << sum << "\n";
    std::cout << "0.1 + 0.2 == 0.3? " << std::boolalpha << (sum == 0.3) << "\n";
}

