import java.util.Arrays;

public class MethodsPassByValue {
    static int square(int n) {
        return n * n;
    }

    static double average(int a, int b) {
        return (a + b) / 2.0;   // 2.0 makes this double division
    }

    static void tryToChange(int n) {
        n = 100;                // changes only the local copy
        System.out.println("inside tryToChange: n = " + n);
    }

    static void addBonus(int[] scores, int bonus) {
        // scores is a copy of the caller's reference: same array, so changes are shared
        for (int i = 0; i < scores.length; i++) {
            scores[i] += bonus;
        }
    }

    static void reassign(int[] scores) {
        scores = new int[]{0, 0};  // rebinds the local copy only
        System.out.println("inside reassign: " + Arrays.toString(scores));
    }

    public static void main(String[] args) {
        System.out.println("square(7) = " + square(7));
        System.out.println("average(80, 95) = " + String.format("%.2f", average(80, 95)));

        int n = 5;
        System.out.println("before tryToChange: n = " + n);
        tryToChange(n);
        System.out.println("after tryToChange: n = " + n);

        int[] scores = {75, 90};
        addBonus(scores, 5);
        System.out.println("after addBonus(scores, 5): " + Arrays.toString(scores));
        reassign(scores);
        System.out.println("after reassign: " + Arrays.toString(scores));
    }
}

