public class ClassesCircleBlueprint {
    public static void main(String[] args) {
        Circle unit = new Circle();
        Circle big = new Circle(2.5);

        for (Circle c : new Circle[]{unit, big}) {
            System.out.println(c + " area=" + String.format("%.2f", c.area())
                + " perimeter=" + String.format("%.2f", c.perimeter()));
        }

        System.out.println("setRadius(-3) accepted? " + big.setRadius(-3) + ", still " + big);
        System.out.println("setRadius(4) accepted? " + big.setRadius(4) + ", now " + big);
        System.out.println("radius via getter: " + big.getRadius());
        System.out.println("circles created: " + Circle.getCreated());
    }
}

class Circle {
    private static int created = 0;   // one counter shared by the whole class
    private double radius;            // private: only Circle's methods can touch it

    Circle() {
        this(1.0);                    // delegate to the other constructor
    }

    Circle(double radius) {
        this.radius = radius;         // this.radius is the field, radius the parameter
        created++;
    }

    double getRadius() { return radius; }

    boolean setRadius(double radius) {
        if (radius < 0) return false; // the class protects its own invariant
        this.radius = radius;
        return true;
    }

    double area() { return Math.PI * radius * radius; }

    double perimeter() { return 2 * Math.PI * radius; }

    static int getCreated() { return created; }

    @Override
    public String toString() {
        return String.format("Circle(r=%.2f)", radius);
    }
}

