class Circle {
    inline static int created = 0;  // static member shared by all circles
    double radius;

public:
    Circle() : Circle(1.0) {}  // delegating constructor, like this(1.0)

    explicit Circle(double radius) : radius(radius) { ++created; }

    double getRadius() const { return radius; }

    bool setRadius(double r) {
        if (r < 0) return false;
        radius = r;
        return true;
    }

    double area() const { return M_PI * radius * radius; }

    double perimeter() const { return 2 * M_PI * radius; }

    static int getCreated() { return created; }

    std::string toString() const {
        char buf[32];
        std::snprintf(buf, sizeof buf, "Circle(r=%.2f)", radius);
        return buf;
    }
};

int main() {
    Circle unit;
    Circle big(2.5);

    for (const Circle* c : {&unit, &big}) {
        std::printf("%s area=%.2f perimeter=%.2f\n", c->toString().c_str(), c->area(), c->perimeter());
    }

    bool ok = big.setRadius(-3);
    std::cout << std::boolalpha << "setRadius(-3) accepted? " << ok << ", still " << big.toString() << "\n";
    ok = big.setRadius(4);
    std::cout << "setRadius(4) accepted? " << ok << ", now " << big.toString() << "\n";
    // Print 4.0 the way Java prints a double with no fraction
    std::printf("radius via getter: %.1f\n", big.getRadius());
    std::cout << "circles created: " << Circle::getCreated() << "\n";
}

