import java.util.Objects;

public class ObjectsIdentityEquality {
    public static void main(String[] args) {
        Point p = new Point(1, 2);
        Point q = p;                  // no new object: q is an alias of p
        Point r = new Point(4, 5);    // a separate object
        System.out.println("p = " + p + ", q = " + q + ", r = " + r);

        q.move(3, 3);                 // changes the one object both p and q refer to
        System.out.println("after q.move(3, 3): p = " + p + ", q = " + q);

        System.out.println("p == q (same object): " + (p == q));
        System.out.println("p == r (same object): " + (p == r));
        System.out.println("p.equals(r) (same contents): " + p.equals(r));

        Point[] pts = {new Point(0, 0), new Point(0, 0)};
        pts[0].move(1, 0);            // each object keeps its own state
        System.out.println("pts[0] = " + pts[0] + ", pts[1] = " + pts[1]);
    }
}

class Point {
    private int x;
    private int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    void move(int dx, int dy) {
        x += dx;
        y += dy;
    }

    // equals compares contents; == compares references
    @Override
    public boolean equals(Object o) {
        return o instanceof Point other && x == other.x && y == other.y;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);   // equal objects must have equal hash codes
    }

    @Override
    public String toString() {
        return "(" + x + ", " + y + ")";
    }
}

